# region: emit
def emit(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: gather
def gather(xs, factor=10):
    return [v * factor for v in xs]

# region: fold
def fold(xs, limit=20):
    return [v if v <= limit else limit for v in xs]

# region: digest
def digest(xs):
    return [v * v for v in xs]

# region: intake
def intake(xs):
    d = {}
    for v in xs[:-1]:
        d[v % 3] = d.get(v % 3, 0) + 1
    return {'n': len(xs), 'tally': sorted(d.items())}

# region: render
def render(summary, name='beta'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return render(intake(digest(fold(gather(emit(raw))))))

